/*
 * Lightweight, dependency-free controller for search + sort + filter +
 * pagination on a plain server-rendered <table>. No row markup is ever
 * generated by this script -- it only shows/hides/reorders the <tr>
 * elements that are already in the DOM, so nothing about how a table's
 * rows are built or what actions they contain needs to change.
 *
 * Opt in per-table by adding `data-datatable` to the <table>, plus
 * whichever of these companion attributes that table actually uses:
 *
 *   data-datatable                    marks the table as controlled
 *   data-dt-search="#selector"        text input; fuzzy-matches full row text
 *   data-dt-filters="#selector"       container holding filter checkboxes
 *   data-dt-page-size="#selector"     <select> of page sizes
 *   data-dt-page-size-default="10"    fallback page size if no <select>
 *   data-dt-summary="#selector"       element to receive "Showing X to Y of Z"
 *   data-dt-pagination="#selector"    <ul> to receive Tabler pagination markup
 *
 * Sortable columns: any button with class "table-sort" inside the
 * table's <thead>, with data-sort-key (matched against the row's
 * data-<key> attribute) and data-sort-type ("text", the default, or
 * "number"). Tabler's own CSS draws the sort arrow via ::after based on
 * an "asc"/"desc" class on the button -- this script only toggles that
 * class, it doesn't touch any icon markup itself.
 *
 * Filter checkboxes: inside the element referenced by data-dt-filters,
 * any <input type="checkbox" data-filter-group="..." value="...">.
 * Checkboxes sharing a group are OR'd together; different groups are
 * AND'd together. A row matches a group once at least one of that
 * group's checked values equals the row's data-<group> attribute (a
 * group with nothing checked imposes no constraint). An element with
 * [data-dt-clear-filters] inside the same container clears every
 * checkbox in it, plus the search box, when clicked.
 *
 * Search: matches if every whitespace-separated term in the query is a
 * substring of the row's full text content -- a simple, dependency-free
 * stand-in for fuzzy matching across any column.
 */
(function () {
  'use strict';

  function normalize(text) {
    return (text || '').toString().trim().toLowerCase();
  }

  function matchesSearch(row, query) {
    if (!query) return true;
    const terms = normalize(query).split(/\s+/).filter(Boolean);
    const haystack = normalize(row.textContent);
    return terms.every((term) => haystack.includes(term));
  }

  function initTable(table) {
    const tbody = table.querySelector('tbody');
    if (!tbody) return;
    const rows = Array.from(tbody.children).filter((el) => el.tagName === 'TR');

    const searchInput = table.dataset.dtSearch ? document.querySelector(table.dataset.dtSearch) : null;
    const filtersEl = table.dataset.dtFilters ? document.querySelector(table.dataset.dtFilters) : null;
    const pageSizeEl = table.dataset.dtPageSize ? document.querySelector(table.dataset.dtPageSize) : null;
    const summaryEl = table.dataset.dtSummary ? document.querySelector(table.dataset.dtSummary) : null;
    const paginationEl = table.dataset.dtPagination ? document.querySelector(table.dataset.dtPagination) : null;

    const sortButtons = Array.from(table.querySelectorAll('thead .table-sort'));
    const filterChecks = filtersEl
      ? Array.from(filtersEl.querySelectorAll('input[type="checkbox"][data-filter-group]'))
      : [];
    const clearFiltersEl = filtersEl ? filtersEl.querySelector('[data-dt-clear-filters]') : null;

    const defaultPageSize = parseInt(
      (pageSizeEl && pageSizeEl.value) || table.dataset.dtPageSizeDefault || '10',
      10
    ) || 10;

    const state = {
      page: 1,
      pageSize: defaultPageSize,
      sortKey: null,
      sortType: 'text',
      sortDir: 'asc',
      search: '',
    };

    function activeFilterGroups() {
      const groups = {};
      filterChecks.forEach((cb) => {
        if (!cb.checked) return;
        const group = cb.dataset.filterGroup;
        (groups[group] = groups[group] || []).push(cb.value);
      });
      return groups;
    }

    function matchesFilters(row, groups) {
      return Object.keys(groups).every((group) => {
        const values = groups[group];
        return !values.length || values.includes(row.dataset[group]);
      });
    }

    function compareRows(a, b) {
      if (!state.sortKey) return 0;
      let av = a.dataset[state.sortKey] || '';
      let bv = b.dataset[state.sortKey] || '';
      if (state.sortType === 'number') {
        av = parseFloat(av) || 0;
        bv = parseFloat(bv) || 0;
        if (av === bv) return 0;
        return state.sortDir === 'asc' ? av - bv : bv - av;
      }
      av = normalize(av);
      bv = normalize(bv);
      if (av === bv) return 0;
      const cmp = av < bv ? -1 : 1;
      return state.sortDir === 'asc' ? cmp : -cmp;
    }

    function updateSortIndicators() {
      sortButtons.forEach((btn) => {
        btn.classList.remove('asc', 'desc');
        if (btn.dataset.sortKey === state.sortKey) btn.classList.add(state.sortDir);
      });
    }

    function pageItem(label, page, opts) {
      opts = opts || {};
      const item = document.createElement('li');
      item.className = 'page-item' + (opts.disabled ? ' disabled' : '') + (opts.active ? ' active' : '');
      const link = document.createElement(opts.disabled || opts.active ? 'span' : 'a');
      link.className = 'page-link';
      link.innerHTML = label;
      if (!opts.disabled && !opts.active) {
        link.href = '#';
        link.addEventListener('click', (e) => {
          e.preventDefault();
          state.page = page;
          render();
        });
      }
      item.appendChild(link);
      return item;
    }

    function renderPagination(totalPages) {
      if (!paginationEl) return;
      paginationEl.innerHTML = '';
      if (totalPages <= 1) return;

      paginationEl.appendChild(
        pageItem('<i class="ti ti-chevron-left"></i>', state.page - 1, { disabled: state.page <= 1 })
      );

      const shown = Array.from(new Set([1, totalPages, state.page - 1, state.page, state.page + 1]))
        .filter((p) => p >= 1 && p <= totalPages)
        .sort((a, b) => a - b);

      let last = 0;
      shown.forEach((p) => {
        if (last && p - last > 1) paginationEl.appendChild(pageItem('&hellip;', 0, { disabled: true }));
        paginationEl.appendChild(pageItem(String(p), p, { active: p === state.page }));
        last = p;
      });

      paginationEl.appendChild(
        pageItem('<i class="ti ti-chevron-right"></i>', state.page + 1, { disabled: state.page >= totalPages })
      );
    }

    function render() {
      const groups = activeFilterGroups();
      const filtered = rows
        .filter((r) => matchesFilters(r, groups) && matchesSearch(r, state.search))
        .sort(compareRows);

      const total = filtered.length;
      const totalPages = Math.max(1, Math.ceil(total / state.pageSize));
      if (state.page > totalPages) state.page = totalPages;
      if (state.page < 1) state.page = 1;

      const start = total === 0 ? 0 : (state.page - 1) * state.pageSize;
      const end = Math.min(start + state.pageSize, total);

      filtered.forEach((r) => tbody.appendChild(r));
      rows.forEach((r) => { r.style.display = 'none'; });
      filtered.slice(start, end).forEach((r) => { r.style.display = ''; });

      if (summaryEl) {
        summaryEl.textContent = total === 0
          ? 'No matching rows.'
          : `Showing ${start + 1} to ${end} of ${total} entr${total === 1 ? 'y' : 'ies'}`;
      }

      renderPagination(totalPages);
      updateSortIndicators();
    }

    sortButtons.forEach((btn) => {
      btn.addEventListener('click', () => {
        const key = btn.dataset.sortKey;
        if (state.sortKey === key) {
          state.sortDir = state.sortDir === 'asc' ? 'desc' : 'asc';
        } else {
          state.sortKey = key;
          state.sortType = btn.dataset.sortType || 'text';
          state.sortDir = 'asc';
        }
        render();
      });
    });

    filterChecks.forEach((cb) => {
      cb.addEventListener('change', () => {
        state.page = 1;
        render();
      });
    });

    if (clearFiltersEl) {
      clearFiltersEl.addEventListener('click', (e) => {
        e.preventDefault();
        filterChecks.forEach((cb) => { cb.checked = false; });
        if (searchInput) searchInput.value = '';
        state.search = '';
        state.page = 1;
        render();
      });
    }

    if (searchInput) {
      searchInput.addEventListener('input', () => {
        state.search = searchInput.value;
        state.page = 1;
        render();
      });
    }

    if (pageSizeEl) {
      pageSizeEl.value = String(defaultPageSize);
      pageSizeEl.addEventListener('change', () => {
        state.pageSize = parseInt(pageSizeEl.value, 10) || defaultPageSize;
        state.page = 1;
        render();
      });
    }

    render();
  }

  document.addEventListener('DOMContentLoaded', () => {
    document.querySelectorAll('table[data-datatable]').forEach(initTable);
  });
})();
